        tool: 'datalint',
        version: require('../package.json').version,
        generatedAt: new Date().toISOString(),
        mode: 'clean',
        ...extra,
        rules: { required, minLen, maxLen, dedup: '规范化整行（键排序 + trim 后比较）', fix: '字符串字段 trim' },
