  if (opts.mode === 'check' && usedCleanOnly.length > 0) {
    throw new UsageError(`选项 ${usedCleanOnly[0]} 仅 clean 模式可用（用法：datalint clean ...）`);
  }
  if (opts.minLen !== null && opts.maxLen !== null && opts.minLen > opts.maxLen) {
